SELECT a.*
FROM attendance a
    LEFT JOIN employee e
        ON a.employee_id = e.employee_id
    LEFT JOIN department d
        ON d.department_id = e.department_id
WHERE 1=1


    AND d.department_id = #{departmentId}


AND a.work_date >= #{startDate}
AND a.work_date < #{endDate}

LIMIT #{size} OFFSET #{offset}

select * from employee e left join ( select * from attendance a where 1=1
and DATE(a.work_date) = #{findDate}
) a on a.employee_id = e.employee_id left join positions p on e.position_id = p.position_id left join department d on e.department_id= d.department_id where 1=1
and e.name like CONCAT('%', #{keyword}, '%')
and d.department_name = #{departmentName}

select * from employee e left join ( select * from attendance a where 1=1
and DATE(a.created_at) = #{findDate}
) a on a.employee_id = e.employee_id left join positions p on e.position_id = p.position_id left join department d on e.department_id= d.department_id

select * from attendance
where work_date = #{now}
and employee_id = #{employeeId}

select * from attendance
where work_date = #{findDate}
and employee_id = #{employeeId}

select *
    from attendance a
left join employee e
on e.employee_id = a.employee_id
left join department d
on e.department_id = d.department_id

where a.work_date >= #{startMonth}

  AND a.work_date < #{endMonth}

and a.employee_id = #{employeeId}

    and d.department_name = #{departmentName}

select * from attendance a
where employee_id = #{employeeId}
and work_date >= #{startMonth}

